/**
 * Mini D: a small, hand-written synth definition for the synth library's unit tests.
 *
 * A cut-down Model D (three oscillators, mixer, ladder filter, two contours, one LFO, a mod bus) plus a patch bay
 * whose jacks reach every kind of engine destination the cable explainer groups by (pitch, pulse width, cutoff,
 * resonance, loudness, LFO rate, waveform, level, delay time, triggers, audio inputs, utilities), and one output
 * per kind of source (LFO, envelope, gate, keyboard, noise, audio, a utility). It is not a copy of any real panel:
 * coordinates are tidy, and every control and jack sits inside exactly one area.
 *
 * `toEngine` is a real, pure mapping, so the explainer, the sound map and the wave story can run on it.
 * Hand-written, not generated: the app never imports the prototype.
 */
import { expMap, fmtHz, fmtSemi, level10, pwl } from '@/lib/app/synths/lib/maps';
import type {
  Area,
  Control,
  ControlValues,
  EngineParams,
  Jack,
  SynthDef,
} from '@/lib/app/synths/contract';

