/** Output jack ids, one per kind of source the explainer tells apart. */
const out = (id: string, x: number, y: number, signal: string | null, label: string): Jack => ({
  id,
  x,
  y,
  r: 12,
  label,
  help: `${label} output.`,
  dir: 'out',
  signal,
});
const inp = (
  id: string,
  x: number,
  y: number,
  dest: string | null,
  label: string,
  rest: Partial<Extract<Jack, { dir: 'in' }>> = {}
): Jack => ({ id, x, y, r: 12, label, help: `${label} input.`, dir: 'in', dest, ...rest });

