const WAVE_MIX: Record<string, Record<string, number>> = {
  tri: { tri: 1 },
  saw: { saw: 1 },
  sq: { pulse: 1 },
};

const num = (v: ControlValues, id: string) => Number(v[id]);

/** Panel values → engine parameters. Pure; ignores the `ui` control. */
export function miniToEngine(v: ControlValues): EngineParams {
  const depth = num(v, 'mod.depth') / 10;
  return {
    osc: [
      {
        level: level10(num(v, 'mix.osc1')),
        mix: WAVE_MIX[String(v['osc1.wave'])],
        pw: 0.5,
        semi: RANGE_SEMI[String(v['osc1.range'])] ?? 0,
      },
      {
        level: level10(num(v, 'mix.osc2')),
        mix: WAVE_MIX[String(v['osc2.wave'])],
        pw: 0.5,
        semi: num(v, 'osc2.detune'),
        syncTo: -1,
      },
      { level: 0, mix: { tri: 1 }, semi: 0, kbd: v['osc3.kbd'] !== false },
    ],
    noise: { level: level10(num(v, 'mix.noise')) },
    ext: { level: 1 },
    filter: {
      type: 'ladder',
      mode: 'lp',
      cutoff: expMap((num(v, 'filter.cutoff') + 5) / 10, 20, 20000),
      res: num(v, 'filter.emphasis') / 10,
      envAmt: num(v, 'filter.contour') / 2.5,
      envSrc: 'env1',
      kbd: 0.5,
    },
    env1: { a: envTime(num(v, 'env1.attack')), d: 0.3, s: 0.4, r: 0.3 },
    env2: { a: envTime(num(v, 'env2.attack')), d: 0.3, s: num(v, 'env2.sustain') / 10, r: 0.2 },
    vca: { envSrc: 'env2', bias: 0 },
    lfo: {
      rate: expMap(num(v, 'lfo.rate') / 10, 0.05, 200),
      mix: { [String(v['lfo.shape'])]: 1 },
      keySync: false,
    },
    glide: { time: 0, legato: false },
    trig: { retrig: true, drone: false, repeat: false },
    volume: num(v, 'out.volume') / 10,
    routes: v['mod.toOsc'] && depth > 0 ? [{ src: 'lfoTri', dst: 'pitchAll', amt: depth * 2 }] : [],
    sh: { rate: 4, glide: 0 },
    slew: { time: 0.1 },
    att: [0.5, 1],
    delay: { on: true, time: 0.3, fb: 0.3, mix: 0.4 },
  };
}

/** A fresh Mini D. Each call returns new objects, so a test may annotate or mutate its own copy. */
export function makeMiniD(overrides: Partial<SynthDef> = {}): SynthDef {
  const controls = MINI_CONTROLS.map((c) => ({ ...c }));
  const init = Object.fromEntries(controls.map((c) => [c.id, c.def]));
  return {
    id: 'mini-d',
    name: 'Mini D',
    maker: 'Test',
    year: 2026,
    heritage: 'A test synth in the shape of a Minimoog',
    summary: 'Three oscillators, a mixer, a ladder filter and two contours, with a patch bay.',
    view: { w: 1300, h: 400 },
    theme: { panel: '#222', panel2: '#111', ink: '#eee', font: 'din', cheeks: 'wood', cheekW: 0 },
    decor: [
      { t: 'frame', x: 10, y: 10, w: 280, h: 380, label: 'OSCILLATOR BANK' },
      { t: 'text', x: 400, y: 30, text: 'MIXER' },
      { t: 'line', x1: 500, y1: 0, x2: 500, y2: 400 },
      { t: 'path', d: 'M820 260 H980' },
      { t: 'rect', x: 0, y: 380, w: 1300, h: 20 },
    ],
    areas: MINI_AREAS.map((a) => ({ ...a, rects: a.rects.map((r) => ({ ...r })) })),
    controls,
    jacks: MINI_JACKS.map((j) => ({ ...j })),
    init,
    toEngine: miniToEngine,
    signalNames: { env1: 'the filter contour', env2: 'the loudness contour' },
    ...overrides,
  };
}
